28	export class McpClientManager {
29	  private clients: Map<string, McpClient> = new Map();
30	  // Track all configured servers (including disabled ones) for UI display
31	  private allServerConfigs: Map<string, MCPServerConfig> = new Map();
32	  private readonly clientVersion: string;
33	  private readonly toolRegistry: ToolRegistry;
34	  private readonly cliConfig: Config;
35	  // If we have ongoing MCP client discovery, this completes once that is done.
36	  private discoveryPromise: Promise<void> | undefined;
37	  private discoveryState: MCPDiscoveryState = MCPDiscoveryState.NOT_STARTED;
38	  private readonly eventEmitter?: EventEmitter;
39	  private pendingRefreshPromise: Promise<void> | null = null;
40	  private readonly blockedMcpServers: Array<{
41	    name: string;
42	    extensionName: string;
43	  }> = [];
44	
45	  /**
46	   * Track whether the user has explicitly interacted with MCP in this session
47	   * (e.g. by running an /mcp command).
48	   */
49	  private userInteractedWithMcp: boolean = false;
50	
51	  /**
52	   * Track which MCP diagnostics have already been shown to the user this session
53	   * and at what verbosity level.
54	   */
55	  private shownDiagnostics: Map<string, 'silent' | 'verbose'> = new Map();
56	
57	  /**
58	   * Track whether the MCP "hint" has been shown.
59	   */
60	  private hintShown: boolean = false;
61	
62	  /**
63	   * Track the last error message for each server.
64	   */
65	  private lastErrors: Map<string, string> = new Map();
66	
67	  constructor(
68	    clientVersion: string,
69	    toolRegistry: ToolRegistry,
70	    cliConfig: Config,
71	    eventEmitter?: EventEmitter,
72	  ) {
73	    this.clientVersion = clientVersion;
74	    this.toolRegistry = toolRegistry;
75	    this.cliConfig = cliConfig;
76	    this.eventEmitter = eventEmitter;
77	  }
78	
79	  setUserInteractedWithMcp() {
80	    this.userInteractedWithMcp = true;
81	  }
82	
83	  getLastError(serverName: string): string | undefined {
84	    return this.lastErrors.get(serverName);
85	  }
86	
87	  /**
88	   * Emit an MCP diagnostic message, adhering to the user's intent and
89	   * deduplication rules.
90	   */
91	  emitDiagnostic(
92	    severity: 'info' | 'warning' | 'error',
93	    message: string,
94	    error?: unknown,
95	    serverName?: string,
96	  ) {
97	    // Capture error for later display if it's an error/warning
98	    if (severity === 'error' || severity === 'warning') {
99	      if (serverName) {
100	        this.lastErrors.set(serverName, message);
101	      }
102	    }
103	
104	    // Deduplicate
105	    const diagnosticKey = `${severity}:${message}`;
106	    const previousStatus = this.shownDiagnostics.get(diagnosticKey);
107	
108	    // If user has interacted, show verbosely unless already shown verbosely
109	    if (this.userInteractedWithMcp) {
110	      if (previousStatus === 'verbose') {
111	        debugLogger.debug(
112	          `Deduplicated verbose MCP diagnostic: ${diagnosticKey}`,
113	        );
114	        return;
115	      }
116	      this.shownDiagnostics.set(diagnosticKey, 'verbose');
117	      coreEvents.emitFeedback(severity, message, error);
118	      return;
119	    }
120	
121	    // In silent mode, if it has been shown at all, skip
122	    if (previousStatus) {
123	      debugLogger.debug(`Deduplicated silent MCP diagnostic: ${diagnosticKey}`);
124	      return;
125	    }
126	    this.shownDiagnostics.set(diagnosticKey, 'silent');
127	
128	    // Otherwise, be less annoying
129	    debugLogger.log(`[MCP ${severity}] ${message}`, error);
130	
131	    if (severity === 'error' || severity === 'warning') {
132	      if (!this.hintShown) {
133	        this.hintShown = true;
134	        coreEvents.emitFeedback(
135	          'info',
136	          'MCP issues detected. Run /mcp list for status.',
137	        );
138	      }
139	    }
140	  }
