162	        if (config?.extension?.id === extension.id) {
163	          this.allServerConfigs.delete(name);
164	          // Also remove from blocked servers if present
165	          const index = this.blockedMcpServers.findIndex(
166	            (s) => s.name === name && s.extensionName === extension.name,
167	          );
168	          if (index !== -1) {
169	            this.blockedMcpServers.splice(index, 1);
170	          }
171	          return this.disconnectClient(name, true);
172	        }
173	        return Promise.resolve();
174	      }),
