181	   *
182	   *    - Adds all its MCP servers to the global configuration object.
183	   *    - Connects MCP clients to each server and discovers their tools.
184	   *    - Updates the Gemini chat configuration to load the new tools.
185	   */
186	  async startExtension(extension: GeminiCLIExtension) {
187	    debugLogger.log(`Loading extension: ${extension.name}`);
188	    await Promise.all(
189	      Object.entries(extension.mcpServers ?? {}).map(([name, config]) =>
190	        this.maybeDiscoverMcpServer(name, {
191	          ...config,
192	          extension,
193	        }),
194	      ),
195	    );
196	    await this.scheduleMcpContextRefresh();
197	  }
