function mergeExcludeTools(
  a: string[] | undefined,
  b: string[] | undefined,
): string[] | undefined {
  if (a === undefined && b === undefined) {
    return undefined;
  }
  return Array.from(new Set([...(a ?? []), ...(b ?? [])]));
}

/**
 * Combine two `includeTools` lists. When both lists are provided the result is
 * their intersection (an empty array when they do not overlap). When only one
 * list is provided it is used in its entirety.
 */
function mergeIncludeTools(
  user: string[] | undefined,
  extension: string[] | undefined,
): string[] | undefined {
  if (user !== undefined && extension !== undefined) {
    const extensionSet = new Set(extension);
    return user.filter((tool) => extensionSet.has(tool));
  }
  return user ?? extension;
}

/**
 * Shallow-merge two `env` maps, giving precedence to the user-supplied values
 * on conflicts while keeping non-conflicting keys from both.
 */
function mergeEnv(
  user: Record<string, string> | undefined,
  extension: Record<string, string> | undefined,
): Record<string, string> | undefined {
  if (user === undefined && extension === undefined) {
    return undefined;
  }
  return { ...(extension ?? {}), ...(user ?? {}) };
}

/**
 * Merge a user-supplied MCP server configuration with an extension-supplied one
 * for the same server name.
 *
 * The merge is independent of the order the two configs are registered in: the
 * config carrying a {@link GeminiCLIExtension} is always treated as the
 * extension config, the other as the user config.
 *
 * Rules:
 *   - `excludeTools`: union of both lists.
 *   - `includeTools`: intersection of both lists (or the single list provided).
 *   - `env`: shallow merge with user values winning on conflicts.
 *   - connection/common properties (e.g. `command`, `args`): user values win,
 *     properties present only in the extension config are preserved.
 *   - `extension`: the extension's {@link GeminiCLIExtension} is retained.
 */
function mergeMcpServerConfigs(
  a: MCPServerConfig,
  b: MCPServerConfig,
): MCPServerConfig {
  const userConfig = a.extension === undefined ? a : b;
  const extensionConfig = a.extension === undefined ? b : a;

  // Base the merged config on the extension config so properties that only
  // exist there are preserved, then layer the user's explicitly-supplied values
